import {
  S3Client,
  PutObjectCommand,
  DeleteObjectCommand,
  GetObjectCommand,
  HeadObjectCommand,
  ListObjectsV2Command,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

// Lazy-initialized: read env vars at call time (after dotenv.config() has run)
let _s3: S3Client | null = null;

function getS3(): S3Client {
  if (!_s3) {
    const accountId = process.env.R2_ACCOUNT_ID;
    const accessKeyId = process.env.R2_ACCESS_KEY_ID;
    const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
    if (!accountId || !accessKeyId || !secretAccessKey) {
      throw new Error('R2 credentials not configured (R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY)');
    }
    _s3 = new S3Client({
      region: 'auto',
      endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
      credentials: { accessKeyId, secretAccessKey },
    });
  }
  return _s3;
}

function getBucket(): string {
  const bucket = process.env.R2_BUCKET_NAME;
  if (!bucket) throw new Error('R2_BUCKET_NAME not configured');
  return bucket;
}

function getPublicUrl(): string {
  return (process.env.R2_PUBLIC_URL ?? '').replace(/\/$/, '');
}

// Keys are always generated by file.service — never taken from a client.
export async function putObject(key: string, buffer: Buffer, contentType: string): Promise<void> {
  await getS3().send(
    new PutObjectCommand({
      Bucket:      getBucket(),
      Key:         key,
      Body:        buffer,
      ContentType: contentType,
    })
  );
}

export async function deleteFromR2(key: string): Promise<void> {
  await getS3().send(new DeleteObjectCommand({ Bucket: getBucket(), Key: key }));
}

// Virtual-hosted origin of the presigned URLs getPresignedUrl() produces
function signedOrigin(): string | null {
  const accountId = process.env.R2_ACCOUNT_ID;
  const bucket = process.env.R2_BUCKET_NAME;
  return accountId && bucket ? `https://${bucket}.${accountId}.r2.cloudflarestorage.com` : null;
}

// The query of a presigned GetObject URL: SigV4 parameters only, signature included
const isPresignQuery = (params: URLSearchParams) =>
  params.has('X-Amz-Signature') && [...params.keys()].every(k => /^X-Amz-/i.test(k) || k === 'x-id');

/**
 * The bucket key behind one of our URLs, or null: a public URL (origin exactly
 * R2_PUBLIC_URL, no query) or a presigned URL of our bucket (exact origin, SigV4
 * query only). A lookalike host (pub-x.r2.dev.evil.com) or a bare string that
 * merely looks like a key is rejected, so callers can never be steered to an
 * arbitrary object. The signature itself is not checked — this only names the
 * object; whether it may be used is claim()'s decision.
 */
export function keyFromUrl(url: string | null | undefined): string | null {
  if (!url) return null;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (parsed.hash) return null;

  let rawKey: string | null = null;
  const publicUrl = getPublicUrl();
  if (publicUrl) {
    try {
      const expected = new URL(publicUrl);
      const basePath = expected.pathname.replace(/\/$/, '');
      if (parsed.origin === expected.origin && !parsed.search && parsed.pathname.startsWith(`${basePath}/`)) {
        rawKey = parsed.pathname.slice(basePath.length + 1);
      }
    } catch { /* misconfigured R2_PUBLIC_URL: public URLs are not recognised */ }
  }
  if (rawKey === null && parsed.origin === signedOrigin() && isPresignQuery(parsed.searchParams)) {
    rawKey = parsed.pathname.slice(1);
  }
  if (rawKey === null) return null;

  const key = decodeURIComponent(rawKey);
  if (!key || key.includes('..')) return null;
  return key;
}

export async function headObject(key: string): Promise<{ sizeBytes: number; contentType: string | null } | null> {
  try {
    const resp = await getS3().send(new HeadObjectCommand({ Bucket: getBucket(), Key: key }));
    return { sizeBytes: Number(resp.ContentLength ?? 0), contentType: resp.ContentType ?? null };
  } catch (err) {
    const status = (err as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode;
    if (status === 404) return null;
    throw err;
  }
}

export async function listAllKeys(): Promise<string[]> {
  const keys: string[] = [];
  let token: string | undefined;
  do {
    const resp = await getS3().send(new ListObjectsV2Command({ Bucket: getBucket(), ContinuationToken: token }));
    for (const obj of resp.Contents ?? []) if (obj.Key) keys.push(obj.Key);
    token = resp.IsTruncated ? resp.NextContinuationToken : undefined;
  } while (token);
  return keys;
}

export async function getPresignedUrl(key: string, expiresInSeconds = 3600): Promise<string> {
  return getSignedUrl(
    getS3(),
    new GetObjectCommand({ Bucket: getBucket(), Key: key }),
    { expiresIn: expiresInSeconds }
  );
}

export async function downloadFromR2(key: string): Promise<Buffer> {
  const resp = await getS3().send(new GetObjectCommand({ Bucket: getBucket(), Key: key }));
  const stream = resp.Body as import('stream').Readable;
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    stream.on('data', (c: Buffer) => chunks.push(c));
    stream.on('end', () => resolve(Buffer.concat(chunks)));
    stream.on('error', reject);
  });
}
